import java.text.Normalizer;
import java.util.List;
import java.util.Locale;

/**
 * Text folding used when matching customers by name.
 *
 * <p>Searching is expected to ignore case and accents in both directions, so
 * both the search terms and the names they are matched against are folded to the
 * same plain, lower-case, accent-free form: {@code Mäkinen}, {@code MAKINEN} and
 * {@code mäkinen} all fold to {@code makinen}.
 *
 * <p>A real backend would do this in the database, with an accent-insensitive
 * collation or a folded index column; this class stands in for that.
 */
public final class SearchText {

    private SearchText() {
    }

    /**
     * Folds text to the form used for matching: lower case, accents removed.
     *
     * @param text text to fold; may be {@code null}
     * @return the folded text, never {@code null}
     */
    public static String fold(String text) {
        if (text == null || text.isEmpty()) {
            return "";
        }
        // NFD splits "ä" into "a" plus a combining mark, which is then dropped.
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD)
                .toLowerCase(Locale.ROOT);
        StringBuilder folded = new StringBuilder(decomposed.length());
        for (int i = 0; i < decomposed.length(); i++) {
            char c = decomposed.charAt(i);
            if (Character.getType(c) == Character.NON_SPACING_MARK) {
                continue;
            }
            // Letters that carry their diacritic inside the letter itself, so
            // NFD leaves them alone.
            switch (c) {
                case 'ß' -> folded.append("ss");
                case 'æ' -> folded.append("ae");
                case 'œ' -> folded.append("oe");
                case 'ø' -> folded.append('o');
                case 'ł' -> folded.append('l');
                case 'đ', 'ð' -> folded.append('d');
                case 'þ' -> folded.append("th");
                default -> folded.append(c);
            }
        }
        return folded.toString();
    }

    /**
     * Splits a search string into folded terms on whitespace. Leading, trailing
     * and repeated whitespace is insignificant, so an empty or blank string
     * yields no terms at all.
     */
    public static List<String> terms(String text) {
        String folded = fold(text).trim();
        if (folded.isEmpty()) {
            return List.of();
        }
        return List.of(folded.split("\\s+"));
    }
}
