[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/customers/domain/CustomerFilter.java", "content": "package com.example.customers.domain;

import java.util.Collection;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * The filter {@link CustomerRepository} narrows its queries with.
 *
 * <p>A customer passes the filter when it satisfies both halves of it:
 * <ul>
 * <li>every whitespace-separated term of {@link #name()} occurs in the
 * customer's first or last name, ignoring case and accents;
 * <li>and its status is one of {@link #statuses()}, unless no status is
 * selected, in which case every status passes.
 * </ul>
 *
 * <p>Instances are canonical: the name is trimmed and its inner whitespace
 * collapsed, and the statuses are held in declaration order. Two filters that
 * select the same customers are therefore equal, which lets the UI skip
 * requerying the backend for a filter it has already run.
 *
 * @param name     the name filter as typed; empty matches every customer
 * @param statuses the statuses to include; empty includes every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = (name == null) ? "" : String.join(" ", name.trim().split("\\s+")).trim();
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** Creates a filter from any collection of statuses. */
    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
        return new CustomerFilter(name, statuses == null ? Set.of() : Set.copyOf(statuses));
    }

    /** {@code true} if this filter narrows nothing down. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /**
     * The name filter as folded terms, all of which a customer must match. Empty
     * when no name was entered.
     *
     * @see SearchText#terms(String)
     */
    public List<String> nameTerms() {
        return SearchText.terms(name);
    }
