+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import com.example.customers.domain.CustomerFilter;
+import com.example.customers.domain.CustomerStatus;
+import com.example.customers.domain.SearchText;
+
+import org.junit.jupiter.api.Test;
+
+/** Unit tests for the filter value object and the text folding behind it. */
+class CustomerFilterTest {
+
+    @Test
+    void foldingIgnoresCaseAndAccents() {
+        assertEquals("makinen", SearchText.fold("Mäkinen"));
+        assertEquals("makinen", SearchText.fold("MAKINEN"));
+        assertEquals("josephine", SearchText.fold("Joséphine"));
+        assertEquals("tomas", SearchText.fold("Tomás"));
+        assertEquals("bergstrom", SearchText.fold("Bergström"));
+        assertEquals("", SearchText.fold(null));
+    }
+
+    @Test
+    void termsSplitOnInsignificantWhitespace() {
+        assertEquals(List.of("ada", "aal"), SearchText.terms("  Ada   AAL "));
+        assertEquals(List.of(), SearchText.terms("   "));
+        assertEquals(List.of(), SearchText.terms(""));
+    }
+
+    @Test
+    void filtersThatSelectTheSameCustomersAreEqual() {
+        assertEquals(CustomerFilter.EMPTY, new CustomerFilter("  ", Set.of()));
+        assertEquals(new CustomerFilter("ada aal", Set.of()),
+                new CustomerFilter(" ada   aal ", null));
+        assertEquals(
+                new CustomerFilter("", Set.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE)),
+                new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)));
+    }
+
+    @Test
+    void statusesKeepDeclarationOrder() {
+        CustomerFilter filter = CustomerFilter.of("",
+                List.of(CustomerStatus.CLOSED, CustomerStatus.ACTIVE));
+        assertEquals(List.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                List.copyOf(filter.statuses()));
+    }
+
+    @Test
+    void emptinessIsAboutBothHalves() {
+        assertTrue(CustomerFilter.EMPTY.isEmpty());
+        assertFalse(new CustomerFilter("vir", Set.of()).isEmpty());
+        assertFalse(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE)).isEmpty());
+    }
+}
