+ * typing actually costs the backend — so this is where those are checked.
+ *
+ * <p>Named {@code ...IT}, so it is not part of {@code mvn test}. Run it with
+ * {@code mvn -o test -Dtest=CustomerListViewPlaywrightIT}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewPlaywrightIT extends AbstractBasePlaywrightIT {
+
+    static {
+        System.setProperty("headless", "true");
+    }
+
+    @LocalServerPort
